-- LOCAL TEST STACK ONLY. A structural replica of the live site's legacy tables (docs/legacy-schema-snapshot.md,
-- 13 Oct 2026) as they are after the 13 Oct hotfix: same names, columns, keys, RLS, grants and read policies, no real data.
-- It makes the local copy behave like production, so migrations that clash with a legacy name fail here first,
-- and the legacy lockdown and its reverse script can be rehearsed. Never run this against the live project.

create table if not exists public.countries (id uuid NOT NULL DEFAULT gen_random_uuid(), code text NOT NULL, name text NOT NULL, registry_name text, registry_url text, api_available boolean DEFAULT false, api_url text, legal_basis text, is_active boolean DEFAULT true, created_at timestamptz DEFAULT now(), constraint countries_code_key UNIQUE (code), constraint countries_pkey PRIMARY KEY (id));
create table if not exists public.companies (id uuid NOT NULL DEFAULT gen_random_uuid(), country_id uuid, company_number text, company_name text NOT NULL, company_name_normalised text, status text, company_type text, incorporated_date date, sic_code text, sic_description text, registered_address_line1 text, registered_address_line2 text, registered_address_city text, registered_address_postcode text, trading_address_full text, trading_address_city text, website text, email text, phone text, opening_hours jsonb, ethiopian_score integer DEFAULT 0, confidence_tier text, address_type text, formation_agent_name text, tier_classification integer, google_place_id text, google_rating numeric, google_review_count integer, facebook_page_url text, ai_description text, profile_published boolean DEFAULT false, profile_published_at timestamptz, next_accounts_due date, next_confirmation_due date, last_accounts_made_up date, requires_manual_review boolean DEFAULT false, source_url text, first_seen_at timestamptz DEFAULT now(), last_updated_at timestamptz DEFAULT now(), is_verified boolean DEFAULT false, contact_email text, verification_token text, manage_token text, email_verified_at timestamptz, submitter_name text, promo_text text, promo_expires_at timestamptz, pending_changes jsonb, country text, address text, instagram text, facebook text, whatsapp text, source text DEFAULT 'user_submission'::text, community_relevant boolean DEFAULT true, is_claimed boolean DEFAULT false, is_featured boolean DEFAULT false, constraint companies_company_number_key UNIQUE (company_number), constraint companies_country_id_fkey FOREIGN KEY (country_id) REFERENCES public.countries(id), constraint companies_pkey PRIMARY KEY (id));
create table if not exists public.sole_traders (id uuid NOT NULL DEFAULT gen_random_uuid(), google_place_id text, business_name text NOT NULL, category text, address_full text, city text, country text, phone text, email text, website text, opening_hours jsonb, google_rating numeric, google_review_count integer, facebook_page_url text, ai_description text, ethiopian_score integer DEFAULT 0, profile_published boolean DEFAULT false, first_seen_at timestamptz DEFAULT now(), last_updated_at timestamptz DEFAULT now(), constraint sole_traders_google_place_id_key UNIQUE (google_place_id), constraint sole_traders_pkey PRIMARY KEY (id));
create table if not exists public.admin_audit (id bigint generated by default as identity NOT NULL, action text NOT NULL, table_name text NOT NULL, listing_id text NOT NULL, listing_name text, created_at timestamptz NOT NULL DEFAULT now(), constraint admin_audit_pkey PRIMARY KEY (id));
create table if not exists public.agent_log (id bigint generated by default as identity NOT NULL, agent_name text NOT NULL, task text NOT NULL, action text NOT NULL, target_id text, result text, metadata jsonb, created_at timestamptz DEFAULT now(), constraint agent_log_pkey PRIMARY KEY (id));
create table if not exists public.business_claims (id uuid NOT NULL DEFAULT gen_random_uuid(), company_id uuid, claimant_name text NOT NULL, claimant_email text NOT NULL, claimant_phone text, verification_method text NOT NULL DEFAULT 'email'::text, verification_code text NOT NULL, code_sent_at timestamptz NOT NULL DEFAULT now(), code_expires_at timestamptz NOT NULL, completed_at timestamptz, ip_address text, attempt_count integer DEFAULT 0, status text NOT NULL DEFAULT 'pending'::text, created_at timestamptz DEFAULT now(), relationship text, section text DEFAULT 'companies'::text, listing_id text, constraint business_claims_company_id_fkey FOREIGN KEY (company_id) REFERENCES public.companies(id) ON DELETE CASCADE, constraint business_claims_pkey PRIMARY KEY (id));
create table if not exists public.cars (id uuid NOT NULL DEFAULT gen_random_uuid(), title text NOT NULL, listing_type text, description text, location text, price text, contact_name text, contact_email text, contact_phone text, status text DEFAULT 'active'::text, created_at timestamptz DEFAULT now(), is_verified boolean DEFAULT false, verification_token text, manage_token text, email_verified_at timestamptz, submitter_name text, pending_changes jsonb, promo_text text, promo_expires_at timestamptz, ai_description text, address text, country text, opening_hours text, instagram text, facebook text, whatsapp text, category text, city text, phone text, website text, constraint cars_pkey PRIMARY KEY (id));
create table if not exists public.claimed_profiles (id uuid NOT NULL DEFAULT gen_random_uuid(), company_id uuid, sole_trader_id uuid, owner_name text NOT NULL, owner_email text NOT NULL, owner_phone text, verified_at timestamptz DEFAULT now(), verification_method text, enhanced_description text, services jsonb, photos jsonb, special_offers text, social_links jsonb, whatsapp_number text, is_active boolean DEFAULT true, constraint claimed_profiles_company_id_fkey FOREIGN KEY (company_id) REFERENCES public.companies(id), constraint claimed_profiles_pkey PRIMARY KEY (id), constraint claimed_profiles_sole_trader_id_fkey FOREIGN KEY (sole_trader_id) REFERENCES public.sole_traders(id));
create table if not exists public.claiming_requests (id uuid NOT NULL DEFAULT gen_random_uuid(), company_id uuid, sole_trader_id uuid, claimant_name text NOT NULL, claimant_email text NOT NULL, claimant_phone text, verification_method text, verification_code text, code_sent_at timestamptz, code_expires_at timestamptz, completed_at timestamptz, ip_address text, device_fingerprint text, attempt_count integer DEFAULT 0, status text DEFAULT 'pending'::text, created_at timestamptz DEFAULT now(), constraint claiming_requests_company_id_fkey FOREIGN KEY (company_id) REFERENCES public.companies(id), constraint claiming_requests_pkey PRIMARY KEY (id), constraint claiming_requests_sole_trader_id_fkey FOREIGN KEY (sole_trader_id) REFERENCES public.sole_traders(id));
create table if not exists public.community (id uuid NOT NULL DEFAULT gen_random_uuid(), name text NOT NULL, category text, description text, location text, contact_name text, contact_email text, contact_phone text, website text, status text DEFAULT 'active'::text, is_verified boolean DEFAULT false, created_at timestamptz DEFAULT now(), verification_token text, manage_token text, email_verified_at timestamptz, submitter_name text, pending_changes jsonb, promo_text text, promo_expires_at timestamptz, ai_description text, address text, country text, opening_hours text, instagram text, facebook text, whatsapp text, city text, phone text, constraint community_pkey PRIMARY KEY (id));
create table if not exists public.delivery (id uuid NOT NULL DEFAULT gen_random_uuid(), title text NOT NULL, submitter_name text, contact_email text, category text, city text, country text, address text, phone text, website text, opening_hours text, instagram text, facebook text, whatsapp text, ai_description text, status text NOT NULL DEFAULT 'pending_verification'::text, verification_token uuid, manage_token uuid, email_verified_at timestamptz, promo_text text, promo_expires_at timestamptz, pending_changes jsonb, is_verified boolean NOT NULL DEFAULT false, price text, created_at timestamptz NOT NULL DEFAULT now(), constraint delivery_pkey PRIMARY KEY (id));
create table if not exists public.directors (id uuid NOT NULL DEFAULT gen_random_uuid(), company_id uuid, director_name text NOT NULL, director_name_normalised text, role text, nationality text, country_of_residence text, date_of_birth_month integer, date_of_birth_year integer, appointed_date date, resigned_date date, is_active boolean DEFAULT true, linguistic_pattern_score integer, linguistic_pattern_detail text, matched_name_pattern text, constraint directors_company_id_fkey FOREIGN KEY (company_id) REFERENCES public.companies(id), constraint directors_pkey PRIMARY KEY (id));
create table if not exists public.events (id uuid NOT NULL DEFAULT gen_random_uuid(), title text NOT NULL, category text, description text, location text, event_date date, event_time text, organiser_name text, contact_email text, status text DEFAULT 'active'::text, is_verified boolean DEFAULT false, created_at timestamptz DEFAULT now(), verification_token text, manage_token text, email_verified_at timestamptz, submitter_name text, pending_changes jsonb, promo_text text, promo_expires_at timestamptz, ai_description text, address text, country text, opening_hours text, instagram text, facebook text, whatsapp text, city text, phone text, website text, constraint events_pkey PRIMARY KEY (id));
create table if not exists public.formation_agent_addresses (id uuid NOT NULL DEFAULT gen_random_uuid(), address_line1 text NOT NULL, postcode text NOT NULL, agent_name text, confirmed_at timestamptz DEFAULT now(), companies_using integer DEFAULT 0, constraint formation_agent_addresses_pkey PRIMARY KEY (id));
create table if not exists public.housing (id uuid NOT NULL DEFAULT gen_random_uuid(), title text NOT NULL, listing_type text, description text, location text, price text, bedrooms integer, contact_name text, contact_email text, contact_phone text, status text DEFAULT 'active'::text, created_at timestamptz DEFAULT now(), is_verified boolean DEFAULT false, verification_token text, manage_token text, email_verified_at timestamptz, submitter_name text, pending_changes jsonb, promo_text text, promo_expires_at timestamptz, ai_description text, address text, country text, opening_hours text, instagram text, facebook text, whatsapp text, category text, city text, phone text, website text, google_place_id text, source text DEFAULT 'user_submission'::text, constraint housing_pkey PRIMARY KEY (id));
create table if not exists public.import_log (google_place_id text NOT NULL, section text NOT NULL, listing_id text, listing_name text, status text NOT NULL DEFAULT 'imported'::text, error text, imported_at timestamptz NOT NULL DEFAULT now(), constraint import_log_pkey PRIMARY KEY (google_place_id, section));
create table if not exists public.jobs (id uuid NOT NULL DEFAULT gen_random_uuid(), title text NOT NULL, company_name text, description text, location text, job_type text, salary_range text, contact_email text, contact_phone text, posted_by_name text, status text DEFAULT 'active'::text, created_at timestamptz DEFAULT now(), expires_at timestamptz, is_verified boolean DEFAULT false, verification_token text, manage_token text, email_verified_at timestamptz, submitter_name text, pending_changes jsonb, promo_text text, promo_expires_at timestamptz, ai_description text, address text, country text, opening_hours text, instagram text, facebook text, whatsapp text, category text, city text, phone text, website text, constraint jobs_pkey PRIMARY KEY (id));
create table if not exists public.listing_enquiries (id bigint generated by default as identity NOT NULL, section text NOT NULL, listing_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), constraint listing_enquiries_pkey PRIMARY KEY (id));
create table if not exists public.made_in_ethiopia (id uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), title text NOT NULL, submitter_name text, contact_email text, category text, ai_description text, city text, country text, address text, phone text, website text, opening_hours text, instagram text, facebook text, whatsapp text, status text NOT NULL DEFAULT 'pending_verification'::text, verification_token text, manage_token text, email_verified_at timestamptz, promo_text text, promo_expires_at timestamptz, pending_changes jsonb, origin_confirmed boolean NOT NULL DEFAULT false, origin_details text, constraint made_in_ethiopia_pkey PRIMARY KEY (id));
create table if not exists public.money (id uuid NOT NULL DEFAULT gen_random_uuid(), title text NOT NULL, service_type text, description text, location text, coverage text, contact_name text, contact_email text, contact_phone text, website text, status text NOT NULL DEFAULT 'pending'::text, is_verified boolean DEFAULT false, created_at timestamptz DEFAULT now(), verification_token text, manage_token text, email_verified_at timestamptz, submitter_name text, pending_changes jsonb, promo_text text, promo_expires_at timestamptz, ai_description text, address text, country text, opening_hours text, instagram text, facebook text, whatsapp text, category text, city text, phone text, constraint money_pkey PRIMARY KEY (id));
create table if not exists public.rate_limits (key text NOT NULL, count integer NOT NULL DEFAULT 1, reset_at timestamptz NOT NULL, constraint rate_limits_pkey PRIMARY KEY (key));
create table if not exists public.tutors (id uuid NOT NULL DEFAULT gen_random_uuid(), name text NOT NULL, subject text, description text, location text, delivery_mode text, rate text, contact_email text, contact_phone text, status text DEFAULT 'active'::text, created_at timestamptz DEFAULT now(), is_verified boolean DEFAULT false, verification_token text, manage_token text, email_verified_at timestamptz, submitter_name text, pending_changes jsonb, promo_text text, promo_expires_at timestamptz, ai_description text, address text, country text, opening_hours text, instagram text, facebook text, whatsapp text, category text, city text, phone text, website text, constraint tutors_pkey PRIMARY KEY (id));

