do $$ begin if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'cars' and policyname = 'Public can read active cars listings') then create policy "Public can read active cars listings" on public.cars as permissive for select to public using ((status = 'active'::text)); end if; end $$;
do $$ begin if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'community' and policyname = 'Public can read active community listings') then create policy "Public can read active community listings" on public.community as permissive for select to public using ((status = 'active'::text)); end if; end $$;
do $$ begin if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'companies' and policyname = 'Public can read active companies listings') then create policy "Public can read active companies listings" on public.companies as permissive for select to public using ((status = 'active'::text)); end if; end $$;
do $$ begin if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'countries' and policyname = 'Public can read countries') then create policy "Public can read countries" on public.countries as permissive for select to anon using (true); end if; end $$;
