do $$ begin if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'made_in_ethiopia' and policyname = 'Public can read active made_in_ethiopia listings') then create policy "Public can read active made_in_ethiopia listings" on public.made_in_ethiopia as permissive for select to public using ((status = 'active'::text)); end if; end $$;
do $$ begin if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'money' and policyname = 'Public can read active money listings') then create policy "Public can read active money listings" on public.money as permissive for select to public using ((status = 'active'::text)); end if; end $$;
